CREATE OR REPLACE FUNCTION public.fn_request_bucket() RETURNS text LANGUAGE sql STABLE SET search_path=public,pg_catalog AS $$ SELECT md5(coalesce(auth.uid()::text,nullif(split_part(coalesce(nullif(current_setting('request.headers',true),'')::jsonb->>'x-forwarded-for','anonymous'),',',1),''),'anonymous')) $$;
REVOKE ALL ON FUNCTION public.fn_request_bucket() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_request_bucket() TO anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.fn_me_email_eligible(p_email text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $$ BEGIN IF length(p_email)>254 OR p_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' THEN RETURN false; END IF; IF NOT public.fn_rate_bucket_hit('me:'||public.fn_request_bucket(),interval '1 hour',5) OR NOT public.fn_rate_bucket_hit('me:global',interval '1 hour',100) THEN RETURN false; END IF; RETURN EXISTS(SELECT 1 FROM public.referrers WHERE lower(email)=lower(btrim(p_email))) OR EXISTS(SELECT 1 FROM auth.users WHERE lower(email)=lower(btrim(p_email))); END $$;
REVOKE ALL ON FUNCTION public.fn_me_email_eligible(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_me_email_eligible(text) TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.fn_submit_public_capture(p_kind text,p_data jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $$ DECLARE allowed_events text[] := ARRAY['page_viewed','signup_viewed','signup_submitted','signup_succeeded','signup_failed','onboarding_started','onboarding_completed','go_live_clicked','publish_page_clicked','checkout_redirected','checkout_canceled','email_lead_submitted','referral_submitted','sample_page_viewed','promo_popup_shown','promo_cta_clicked','invite_link_opened','invite_code_entered','invite_landing_viewed','signup_form_started','invite_cta_clicked','cta_clicked','demo_started','demo_completed','page_published','first_ask_prepared','pwa_install_prompted','pwa_installed','pwa_install_cta_shown','pwa_install_cta_clicked','dashboard_viewed','onboarding_step_completed','publish_banner_seen','publish_succeeded','publish_failed','share_tools_viewed','checkout_succeeded','campaigns_tab_viewed','campaign_segment_selected','campaign_preview_viewed','campaign_send_clicked','campaign_sent','campaign_send_failed','referral_page_load_failed']; BEGIN IF p_kind NOT IN ('funnel_events','mock_inquiries','callback_requests','email_leads') OR jsonb_typeof(p_data)<>'object' OR length(p_data::text)>8000 THEN RAISE EXCEPTION 'invalid_capture'; END IF; IF NOT public.fn_rate_bucket_hit('capture:'||p_kind||':'||public.fn_request_bucket(),interval '1 hour',CASE WHEN p_kind='funnel_events' THEN 300 ELSE 10 END) OR NOT public.fn_rate_bucket_hit('capture:global:'||p_kind,interval '1 hour',CASE WHEN p_kind='funnel_events' THEN 10000 ELSE 200 END) THEN RAISE EXCEPTION 'rate_limited'; END IF;
IF p_kind='funnel_events' THEN IF NOT (p_data->>'event'=ANY(allowed_events)) OR length(coalesce(p_data->>'session_id',''))>64 OR length(coalesce(p_data->>'path',''))>512 OR length(coalesce(p_data->>'referrer',''))>512 OR length(coalesce(p_data->>'user_agent',''))>512 THEN RAISE EXCEPTION 'invalid_event'; END IF; INSERT INTO public.funnel_events(event,session_id,path,referrer,user_agent,meta) VALUES(p_data->>'event',p_data->>'session_id',p_data->>'path',p_data->>'referrer',p_data->>'user_agent',coalesce(p_data->'meta','{}'::jsonb));
ELSIF p_kind='email_leads' THEN IF p_data->>'source' NOT IN ('landing','playbook','sample','marketplace_notify') OR length(coalesce(p_data->>'email',''))>254 OR p_data->>'email' !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' THEN RAISE EXCEPTION 'invalid_email'; END IF; INSERT INTO public.email_leads(email,source) VALUES(lower(btrim(p_data->>'email')),p_data->>'source');
ELSIF p_kind='callback_requests' THEN IF length(coalesce(p_data->>'name','')) NOT BETWEEN 1 AND 200 OR length(coalesce(p_data->>'email','')) NOT BETWEEN 3 AND 254 OR p_data->>'email' !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' OR length(coalesce(p_data->>'phone',''))>32 OR length(coalesce(p_data->>'help_with',''))>2000 OR length(coalesce(p_data->>'business_name',''))>200 OR length(coalesce(p_data->>'city',''))>120 THEN RAISE EXCEPTION 'invalid_callback'; END IF; INSERT INTO public.callback_requests(name,email,phone,business_name,city,help_with,is_mock) VALUES(p_data->>'name',lower(btrim(p_data->>'email')),p_data->>'phone',p_data->>'business_name',p_data->>'city',p_data->>'help_with',false);
ELSE IF p_data->>'kind' NOT IN ('contact','quote','referral') OR length(coalesce(p_data->>'listing_slug',''))>100 OR length(coalesce(p_data->>'name',''))>200 OR length(coalesce(p_data->>'email',''))>254 OR length(coalesce(p_data->>'phone',''))>32 OR length(coalesce(p_data->>'message',''))>2000 THEN RAISE EXCEPTION 'invalid_inquiry'; END IF; INSERT INTO public.mock_inquiries(listing_slug,kind,name,email,phone,message,is_mock) VALUES(p_data->>'listing_slug',p_data->>'kind',p_data->>'name',p_data->>'email',p_data->>'phone',p_data->>'message',true); END IF; RETURN true; END $$;
REVOKE ALL ON FUNCTION public.fn_submit_public_capture(text,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_submit_public_capture(text,jsonb) TO anon,authenticated,service_role;
DROP POLICY IF EXISTS "Anyone can record an allowed funnel event" ON public.funnel_events;
DROP POLICY IF EXISTS "Anyone can submit mock inquiries" ON public.mock_inquiries;
DROP POLICY IF EXISTS "Anyone can submit callback requests" ON public.callback_requests;
DROP POLICY IF EXISTS "Anyone can submit an email lead" ON public.email_leads;
DROP POLICY IF EXISTS "Business owners create own triggers" ON public.referral_triggers;
REVOKE INSERT ON public.referral_triggers FROM anon,authenticated;
CREATE OR REPLACE FUNCTION public.fn_create_job_ask(p_business_id uuid,p_data jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $$ DECLARE b public.businesses%ROWTYPE; result uuid; cap integer; BEGIN SELECT * INTO b FROM public.businesses WHERE id=p_business_id; IF b.user_id IS DISTINCT FROM auth.uid() AND coalesce(auth.role(),'')<>'service_role' THEN RAISE EXCEPTION 'not_authorized'; END IF; IF length(p_data::text)>4000 OR length(coalesce(p_data->>'customer_first_name','')) NOT BETWEEN 1 AND 80 OR length(coalesce(p_data->>'customer_email',''))>254 OR length(coalesce(p_data->>'customer_phone',''))>32 OR length(coalesce(p_data->>'service_description',''))>500 OR length(coalesce(p_data->>'technician_name',''))>120 THEN RAISE EXCEPTION 'invalid_job'; END IF; cap:=CASE WHEN public.fn_effective_plan(b.id)='pro' THEN 300 ELSE 50 END; IF NOT public.fn_rate_bucket_hit('job_hour:'||b.id,interval '1 hour',120) OR NOT public.fn_rate_bucket_hit('job_day:'||b.id,interval '1 day',cap) THEN RAISE EXCEPTION 'rate_limited'; END IF; INSERT INTO public.referral_triggers(business_id,source,source_event_id,customer_first_name,customer_email,customer_phone,service_description,technician_name,amount_paid,review_request_status,referral_requires_positive_signal,status,channel,failure_reason,scheduled_send_at) VALUES(b.id,'manual',gen_random_uuid()::text,p_data->>'customer_first_name',nullif(p_data->>'customer_email',''),nullif(p_data->>'customer_phone',''),p_data->>'service_description',p_data->>'technician_name',nullif(p_data->>'amount_paid','')::numeric,CASE WHEN p_data->>'review_request_status'='scheduled' AND nullif(p_data->>'customer_email','') IS NOT NULL AND b.google_review_url ~ '^https://' THEN 'scheduled' ELSE 'off' END,coalesce((p_data->>'referral_requires_positive_signal')::boolean,false),CASE WHEN nullif(p_data->>'customer_email','') IS NULL THEN 'canceled' ELSE 'scheduled' END,CASE WHEN nullif(p_data->>'customer_email','') IS NULL THEN NULL ELSE 'email' END,CASE WHEN nullif(p_data->>'customer_email','') IS NULL THEN 'no_email_send_by_text_from_your_phone' END,now()+make_interval(hours=>b.trigger_delay_hours)) RETURNING id INTO result; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.fn_create_job_ask(uuid,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.fn_create_job_ask(uuid,jsonb) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.fn_validate_webhook_url() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_catalog AS $$ DECLARE host text; BEGIN host:=lower(substring(NEW.url from '^https://([^/:?#]+)')); IF host IS NULL OR host !~ '^[a-z0-9][a-z0-9.-]+\.[a-z]{2,}$' OR host ~ '(^|\.)(localhost|local|internal|invalid|test)$' OR NEW.url ~ '^https://[^/]*@' THEN RAISE EXCEPTION 'invalid_webhook_url'; END IF; RETURN NEW; END $$;
CREATE TRIGGER trg_validate_webhook_url BEFORE INSERT OR UPDATE OF url ON public.webhook_endpoints FOR EACH ROW EXECUTE FUNCTION public.fn_validate_webhook_url();
DO $$ DECLARE c record; BEGIN FOR c IN SELECT conname,pg_get_constraintdef(oid) AS def FROM pg_constraint WHERE conrelid='public.referral_triggers'::regclass AND contype='c' AND pg_get_constraintdef(oid) LIKE '%source%jobber%' LOOP EXECUTE format('ALTER TABLE public.referral_triggers DROP CONSTRAINT %I',c.conname); EXECUTE format('ALTER TABLE public.referral_triggers ADD CONSTRAINT %I CHECK (source IN (''manual'',''stripe'',''jobber'',''api'')) NOT VALID',c.conname); END LOOP; END $$;